refentry.refsect1:
&reftitle.returnvalues;


 Restituisce &true; se value è uno scalare, &false;
 in caso contrario.

  &reftitle.examples;



    Esempio di is_scalar



<?php
function show_var($var) 
{
    if (is_scalar($var)) {
        echo $var, PHP_EOL;
    } else {
        var_dump($var);
    }
}

$pi = 3.1416;
$proteins = array("emoglobina", "citocromo c ossidasi", "ferredossina");

show_var($pi);
show_var($proteins)

?>


    &example.outputs;


3.1416
array(3) {
  [0]=>
  string(10) "emoglobina"
  [1]=>
  string(20) "citocromo c ossidasi"
  [2]=>
  string(12) "ferredossina"
}
